25	    /**
26	     * creates a post
27	     * @param courseId
28	     * @param post
29	     * @return the created post
30	     */
31	    create(courseId: number, post: Post): Observable<EntityResponseType> {
32	        const copy = this.convertPostingDateFromClient(post);
33	        return this.http
34	            .post<Post>(`${this.resourceUrl}${courseId}${PostService.getResourceEndpoint(undefined, post)}`, copy, { observe: 'response' })
35	            .pipe(map(this.convertPostingResponseDateFromServer));
36	    }
