38	    /**
39	     * gets all posts for course by its id, filtered by context if PostContextFilter is passed
40	     * a context to filter posts for can be a course-wide topic, a lecture, or an exercise within a course
41	     * @param courseId
42	     * @param postContextFilter
43	     * @return the posts
44	     */
45	    getPosts(courseId: number, postContextFilter: PostContextFilter): Observable<EntityArrayResponseType> {
46	        let params = new HttpParams();
47	
48	        if (postContextFilter.postSortCriterion) {
49	            params = params.set('postSortCriterion', postContextFilter.postSortCriterion.toString());
50	        }
51	        if (postContextFilter.sortingOrder) {
52	            params = params.set('sortingOrder', postContextFilter.sortingOrder.toString());
53	        }
54	        if (postContextFilter.courseWideChannelIds) {
55	            params = params.set('courseWideChannelIds', postContextFilter.courseWideChannelIds.toString());
56	        }
57	        if (postContextFilter.plagiarismCaseId) {
58	            params = params.set('plagiarismCaseId', postContextFilter.plagiarismCaseId.toString());
59	        }
60	        if (postContextFilter.searchText) {
61	            params = params.set('searchText', postContextFilter.searchText.toString());
62	        }
63	        if (postContextFilter.conversationId) {
64	            params = params.set('conversationId', postContextFilter.conversationId.toString());
65	        }
66	        if (postContextFilter.filterToUnresolved) {
67	            params = params.set('filterToUnresolved', postContextFilter.filterToUnresolved);
68	        }
69	        if (postContextFilter.filterToOwn) {
70	            params = params.set('filterToOwn', postContextFilter.filterToOwn);
71	        }
72	        if (postContextFilter.filterToAnsweredOrReacted) {
73	            params = params.set('filterToAnsweredOrReacted', postContextFilter.filterToAnsweredOrReacted);
74	        }
75	        if (postContextFilter.pagingEnabled) {
76	            params = params.set('pagingEnabled', postContextFilter.pagingEnabled);
77	            params = params.set('page', postContextFilter.page!);
78	            params = params.set('size', postContextFilter.pageSize!);
79	        }
80	        return this.http
81	            .get<Post[]>(`${this.resourceUrl}${courseId}${PostService.getResourceEndpoint(postContextFilter, undefined)}`, {
82	                params,
83	                observe: 'response',
84	            })
85	            .pipe(map(this.convertPostResponseArrayDatesFromServer));
86	    }
87	
88	    /**
89	     * updates a post
90	     * @param courseId
91	     * @param post
92	     * @return the updated post
93	     */
94	    update<T extends Posting>(courseId: number, post: T): Observable<EntityResponseType> {
95	        const copy = this.convertPostingDateFromClient(post);
96	        return this.http
97	            .put<Post>(`${this.resourceUrl}${courseId}${PostService.getResourceEndpoint(undefined, post)}/${post.id}`, copy, { observe: 'response' })
98	            .pipe(map(this.convertPostingResponseDateFromServer));
99	    }
