108	    updatePostDisplayPriority(courseId: number, postId: number, displayPriority: DisplayPriority): Observable<EntityResponseType> {
109	        return this.http
110	            .put(`${this.resourceUrl}${courseId}/messages/${postId}/display-priority`, {}, { params: { displayPriority }, observe: 'response' })
111	            .pipe(map(this.convertPostingResponseDateFromServer));
112	    }
113	
114	    /**
115	     * deletes a post
116	     * @param courseId
117	     * @param post
118	     * @return void
119	     */
120	    delete(courseId: number, post: Post): Observable<HttpResponse<void>> {
121	        return this.http.delete<void>(`${this.resourceUrl}${courseId}${PostService.getResourceEndpoint(undefined, post)}/${post.id}`, { observe: 'response' });
122	    }
123	
124	    /**
125	     * takes an array of posts and converts the date from the server
126	     * @param res
127	     * @return the response with the converted date
128	     */
129	    convertPostResponseArrayDatesFromServer(res: HttpResponse<Post[]>): HttpResponse<Post[]> {
130	        if (res.body) {
131	            res.body.forEach((post: Post) => {
132	                post.creationDate = convertDateFromServer(post.creationDate);
133	                post.answers?.forEach((answer: AnswerPost) => {
134	                    answer.creationDate = convertDateFromServer(answer.creationDate);
135	                });
136	            });
137	        }
138	        return res;
139	    }
