141	    /**
142	     * Determines whether to use the /messages or /posts API endpoints based on the presence of certain properties in the postContextFilter or post objects.
143	     * If any properties related to conversations are present (conversation, conversationId, or courseWideChannelIds), it returns /messages.
144	     * Otherwise, it defaults to /posts.
145	     *
146	     * @param postContextFilter current post context filter in use
147	     * @param post new or updated post
148	     * @return '/messages' or '/posts'
149	     */
150	    private static getResourceEndpoint(postContextFilter?: PostContextFilter, post?: Post): string {
151	        if (post?.conversation || postContextFilter?.conversationId || postContextFilter?.courseWideChannelIds) {
152	            return '/messages';
153	        } else {
154	            return '/posts';
155	        }
