92	     * @return specification used to chain DB operations
93	     */
94	    public static Specification<Post> getCourseWideChannelsSpecification(Long courseId) {
95	        return (root, query, criteriaBuilder) -> {
96	            final var conversationJoin = root.join(Post_.conversation, JoinType.LEFT);
97	            final var isInCoursePredicate = criteriaBuilder.equal(conversationJoin.get(Channel_.COURSE).get(Course_.ID), courseId);
98	            final var isCourseWidePredicate = criteriaBuilder.isTrue(conversationJoin.get(Channel_.IS_COURSE_WIDE));
99	            // make sure we only fetch channels (which are sub types of conversations)
100	            // this avoids the creation of sub queries
101	            final var isChannelPredicate = criteriaBuilder.equal(conversationJoin.type(), criteriaBuilder.literal(Channel.class));
102	            return criteriaBuilder.and(isInCoursePredicate, isCourseWidePredicate, isChannelPredicate);
103	        };
104	    }
