110	     * @param userId      id of the calling user
111	     * @return specification used to chain DB operations
112	     */
113	    public static Specification<Post> getOwnSpecification(boolean filterToOwn, Long userId) {
114	        return ((root, query, criteriaBuilder) -> {
115	            if (!filterToOwn) {
116	                return null;
117	            }
118	            else {
119	                Join<Post, AnswerPost> answersJoin = root.join(Post_.ANSWERS, JoinType.LEFT);
120	                Predicate searchInAnswerContent = criteriaBuilder.equal(answersJoin.get(AnswerPost_.AUTHOR).get(User_.ID), userId);
121	                Predicate isPostOwner = criteriaBuilder.equal(root.get(Post_.AUTHOR).get(User_.ID), userId);
122	                return criteriaBuilder.or(isPostOwner, searchInAnswerContent);
123	            }
124	        });
125	    }
