129	     *
130	     * @param answeredOrReacted whether only the Posts calling user has Answered or Reacted to should be fetched or not
131	     * @param userId            id of the calling user
132	     * @return specification used to chain DB operations
133	     */
134	    public static Specification<Post> getAnsweredOrReactedSpecification(boolean answeredOrReacted, Long userId) {
135	        return ((root, query, criteriaBuilder) -> {
136	            if (!answeredOrReacted) {
137	                return null;
138	            }
139	            else {
140	                Join<Post, AnswerPost> joinedAnswers = root.join(Post_.ANSWERS, JoinType.LEFT);
